 const keep=(sel,vals,label)=>{if(!sel)return;const old=sel.value;sel.innerHTML=`<option value="">${label}</option>`+vals.map(v=>`<option value="${String(v).replace(/"/g,'&quot;')}">${prettyId(v)}</option>`).join('');if([...sel.options].some(o=>o.value===old))sel.value=old};
 keep(itemSel,[...new Set(rows.map(x=>x.itemTypeId).filter(Boolean))].sort(),'All crafted items');
 keep(skillSel,[...new Set(rows.map(x=>x.skillId).filter(Boolean))].sort(),'All crafting skills');
