// ---- Gem combiner --------------------------------------------------------------------------------------------
// The witch takes three gems of the same kind and carat and hands back one of that kind half a carat higher for a flat
// fee, and stops at 2 carats (the game's own witch window: "Give three gems of the same kind and carat"). Every figure on the page comes from the four numbers below, so a change at the bench is a change here
// and nothing else. This is separate from transmuting, which swaps a gem's kind without touching its carat.
const GEM_COMBINE_DEFAULTS={base:1000,fee:2500,per:3,step:.5,cap:2};
const GEM_COMBINE_KEY='bxc-gem-combiner';
function gemCombineSettings(){
 const s={...GEM_COMBINE_DEFAULTS};
 try{Object.assign(s,JSON.parse(localStorage.getItem(GEM_COMBINE_KEY)||'{}'))}catch{}
 s.step=+s.step>0?+s.step:.5;
 s.per=3;
 s.base=Math.max(0,+s.base||0);
 s.fee=2500;   // the witch's fee never changes
 s.step=.5;s.cap=2;
 return s;
}
function gemCombineSave(s){try{localStorage.setItem(GEM_COMBINE_KEY,JSON.stringify(s))}catch{}}
// one row per carat the witch will make: what it is worth, what it swallows, and what she charges to get there
function gemLadder(s){
 const steps=Math.max(1,Math.min(12,Math.round(s.cap/s.step)));
 const rows=[];let value=s.base,gems=1,combines=0;
 for(let k=0;k<steps;k++){
  rows.push({k,carat:+(s.step*(k+1)).toFixed(2),value,gems,combines,fees:combines*s.fee});
  value=value*s.per+s.fee;gems*=s.per;combines=combines*s.per+1;
 }
 return rows;
}
// feed a pile of gems back to the witch as far as it will go: what you end up holding, and what it cost
function gemPromote(counts,s){
 const steps=gemLadder(s).length;
 const have=Array.from({length:steps},(_,i)=>Math.max(0,Math.floor(counts[i]||0)));
 let combines=0;
 for(let k=0;k<steps-1;k++){
  const up=Math.floor(have[k]/s.per);
  if(up>0){have[k]-=up*s.per;have[k+1]+=up;combines+=up}
 }
 return {have,combines,fees:combines*s.fee};
}
function gemCaratIndex(carat,s){const i=Math.round((+carat||0)/s.step)-1;return Number.isFinite(i)?i:-1}
const gemCoin=n=>Math.round(n||0).toLocaleString();
// How rare a gem size is. 0.5c to 2c can be made at the witch's bench, so they count as common whatever the drop
// rate; above that a gem has to be found: 2.5c uncommon, 3c semi-rare, 3.5c rare, 4c very rare (always the top). The
// colours follow the game's quality colours (good, excellent, superior, flawless). The find
// rates next to them are the collector's recorded gem finds (the game's files do not hold the drop table).
const GEM_RARITY=[[4,'very rare'],[3.5,'rare'],[3,'semi-rare'],[2.5,'uncommon']];
function gemRarity(c){c=+c;for(const [min,l] of GEM_RARITY)if(c>=min-1e-9)return l;return 'common'}
function gemRarityChip(c){const l=gemRarity(c);return `<span class="tag-chip rar-${l.replace(/ /g,'-')}">${l}</span>`}
// the chip for any rarity word in a note (quality, carats): the same colours
function rarityChip(text){const m=/very rare|semi-rare|uncommon|rare/.exec(text||'');return m?`<span class="tag-chip rar-${m[0].replace(/ /g,'-')}">${text}</span>`:text}
globalThis.bxcRarityChip=rarityChip;
function gemFindShares(){
 const g=((globalThis.BINXONIA_COLLECTOR_SNAPSHOT||{}).gems||[]).filter(x=>Number.isFinite(+x.carat)&&+x.carat>0);
 const m=new Map();for(const x of g){const k=+(+x.carat).toFixed(1);m.set(k,(m.get(k)||0)+1)}
 return {total:g.length,share:c=>g.length?(m.get(+(+c).toFixed(1))||0)/g.length:null,count:c=>m.get(+(+c).toFixed(1))||0};
}
// where a gem of this size can come from: gathering gives every size; monsters of level 10+ give up to 0.5c, 20+ 1c,
// 30+ 1.5c, 40+ 2c (official guide); the witch builds 1c to 2c from three of the size below
function gemHowText(c){c=+c;const mon=c<=2+1e-9?`monsters level ${[10,20,30,40][Math.round(c*2)-1]}+`:'',witch=c>.5+1e-9&&c<=2+1e-9?`the witch (3 × ${+(c-.5).toFixed(1)}c)`:'';
 const parts=['Gathering',mon,witch].filter(Boolean);return parts.length===1?'Gathering only':parts.slice(0,-1).join(', ')+' or '+parts[parts.length-1]}
globalThis.bxcGemHow=gemHowText;
function gemRarityTableHtml(){
 const s=gemCombineSettings(),f=gemFindShares(),rows=[];
 for(let c=.5;c<=4+1e-9;c+=.5){const sh=f.share(c);
  rows.push(`<tr><td>${c}c</td><td>${gemRarityChip(c)}</td><td>${sh==null?'—':(sh*100).toFixed(sh<.1?1:0)+'%'}${f.count(c)?` <span class="muted">(${f.count(c)})</span>`:''}</td><td>${gemHowText(c)}</td></tr>`)}
 return `<div class="g-scroll"><table class="g-table"><thead><tr><th>Carat</th><th>Rarity</th><th>Of gems found</th><th>Where it comes from</th></tr></thead><tbody>${rows.join('')}</tbody></table></div>
 <p class="g-note">Up to 2c can be made at the witch, so those count as common. Bigger gems only come from gathering: 2.5c uncommon, 3c semi-rare, 3.5c rare, 4c very rare.${f.total?` “Of gems found” is out of the ${f.total.toLocaleString()} gems players have recorded.`:''}</p>`;
}
globalThis.bxcGemRarity=gemRarity;globalThis.bxcGemRarityChip=gemRarityChip;globalThis.bxcGemRarityTable=gemRarityTableHtml;

function gemWitchLadderRows(){const s=gemCombineSettings(),rows=gemLadder(s);return rows.map(r=>`<tr${r.k===rows.length-1?' class="gc-top"':''}><td>${r.carat}c</td><td>${r.gems.toLocaleString()}</td><td>${r.combines.toLocaleString()}</td><td>${gemCoin(r.fees)}</td><td>${gemCoin(r.value)}</td></tr>`).join('')}
function gemWitchPlan(){
 const el=id=>document.getElementById(id);if(!el('gcStats'))return;
 const now=gemCombineSettings(),ladder=gemLadder(now);
 const k=Math.max(1,Math.min(ladder.length-1,Math.round(+el('gcTarget').value)||ladder.length-1)),n=Math.max(1,Math.min(999,Math.round(+el('gcHow').value)||1));
 const r=ladder[k],need=r.gems*n,cb=r.combines*n;
 const tile=(v,l)=>`<div class="gc-stat"><b>${v}</b><span>${l}</span></div>`;
 el('gcStats').innerHTML=tile(need.toLocaleString(),'0.5c gems of one kind')+tile(cb.toLocaleString(),'combine'+(cb===1?'':'s'))+tile(gemCoin(cb*now.fee),'in fees')+tile(gemCoin(r.value*n),'total cost');
}
function gemWitchHtml(){
 const s=gemCombineSettings(),rows=gemLadder(s);
 return `<p>The <a href="#/npc/dark-witch">Dark Witch</a> lives in a hut in Midland Forest (her page shows it on the map). She does two things with gems: makes them bigger, and changes their kind.</p>
 <h3>Combine: one size bigger</h3>
 <p>Give her <b>3</b> gems of the <b>same kind and size</b> and <b>${gemCoin(s.fee)}</b> coins; you get back one gem of that kind, half a carat bigger. She goes up to <b>2c</b>.</p>
 <div class="gc-card">
  <div class="tool-form gc-inputs">
   <div><label for="gcTarget">Carat you want</label><select id="gcTarget">${rows.slice(1).map(r=>`<option value="${r.k}"${r.k===rows.length-1?' selected':''}>${r.carat}c</option>`).join('')}</select></div>
   <div><label for="gcHow">How many</label><input id="gcHow" type="number" min="1" max="999" step="1" value="1"></div>
   <div><label for="gcBase">Price paid per 0.5c gem</label><input id="gcBase" type="number" min="0" step="1" value="${s.base}"></div>
  </div>
  <div id="gcStats" class="gc-stats" aria-live="polite"></div>
  <div class="g-scroll"><table class="g-table gc-ladder"><thead><tr><th>Carat</th><th>0.5c gems</th><th>Combines</th><th>Fees</th><th>Total cost</th></tr></thead><tbody id="gcLadder">${gemWitchLadderRows()}</tbody></table></div>
 </div>
 <h3>Transmute: a different kind</h3>
 <p>Give her two gems of the <b>same size</b>; you get back one gem of that size, never the same kind as either. It is how spare gems become the kind you need.</p>
 <h3>What your gems could become</h3>
 <p>Pick a gem, its size and how many you have, to see what they turn into when you combine them as far as she goes.</p>
 <div class="calcgrid tool-form gc-mine">
  <div><label for="gsKind">Gem</label><select id="gsKind">${Object.keys(ENCHANT_GEMS).map(k=>`<option value="${k}">${ENCHANT_GEMS[k].name||prettyId(k)}</option>`).join('')}</select></div>
  <div><label for="gsCarat">Carat</label><select id="gsCarat">${gemLadder(s).slice(0,-1).map(r=>`<option value="${r.carat}">${r.carat}c</option>`).join('')}</select></div>
  <div><label for="gsHave">How many you have</label><input id="gsHave" type="number" min="0" step="1" value="0"></div>
 </div>
 <div id="gsResult" class="gc-result"></div>`;
}
// "What yours could become": that many gems of one carat, combined as far as the witch goes. In the app the count
// starts at what the collector recorded for that gem and carat (bxcGemCount); typing your own number wins until the
// gem or carat is changed again.
function gemMineFill(){const el=id=>document.getElementById(id),have=el('gsHave');if(!have||have.dataset.typed||typeof globalThis.bxcGemCount!=='function')return;
 have.value=String(globalThis.bxcGemCount(el('gsKind').value,+el('gsCarat').value)||0)}
function gemMinePlan(){
 const el=id=>document.getElementById(id);if(!el('gsResult'))return;
 const s=gemCombineSettings(),rows=gemLadder(s),i=gemCaratIndex(+el('gsCarat').value,s),n=Math.max(0,Math.floor(+el('gsHave').value||0));
 const counts=Array(rows.length).fill(0);if(i>=0&&i<rows.length)counts[i]=n;
 // what comes out is only the bigger sizes; gems at the carat you started with are just left over
 const r=gemPromote(counts,s),pills=[];for(let k=r.have.length-1;k>i;k--)if(r.have[k])pills.push(`<span class="gc-pill"><b>${r.have[k]}</b> × ${rows[k].carat}c</span>`);
 const left=i>=0&&r.have[i]?`<span class="muted">${r.have[i]} × ${rows[i].carat}c left over</span>`:'';
 el('gsResult').innerHTML=!n?'<span class="muted">Enter how many you have.</span>':!r.combines?`<span class="muted">Not enough to combine: the witch needs ${s.per} of one carat.</span>`
  :`<span class="gc-result-h">Becomes</span>${pills.join('')}${left}<span class="gc-result-fee"><b>${gemCoin(r.fees)}</b> in fees · ${r.combines} combine${r.combines===1?'':'s'}</span>`;
}
globalThis.bxcGemMineRefresh=()=>{gemMineFill();gemMinePlan()};
globalThis.bxcGemWitchHtml=gemWitchHtml;globalThis.bxcGemWitchPlan=gemWitchPlan;
document.addEventListener('input',e=>{const id=e.target&&e.target.id;
 if(id==='gsHave'){e.target.dataset.typed='1';gemMinePlan();return}
 if(id==='gcTarget'||id==='gcHow')gemWitchPlan();
 else if(id==='gcBase'){const el=x=>document.getElementById(x);gemCombineSave({base:Math.max(0,+el('gcBase').value||0)});el('gcLadder').innerHTML=gemWitchLadderRows();gemWitchPlan()}});
document.addEventListener('change',e=>{const id=e.target&&e.target.id;if(id==='gcTarget')gemWitchPlan();
 if(id==='gsKind'||id==='gsCarat'){const h=document.getElementById('gsHave');if(h)delete h.dataset.typed;gemMineFill();gemMinePlan()}});
