document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('on'));b.classList.add('on');tab=b.dataset.tab;if(b.dataset.calc)calcGroup=b.dataset.calc;guideGroup=b.dataset.ggroup||null;render()});
content.addEventListener('click',e=>{const b=e.target.closest('[data-weak],[data-resist]');if(!b||tab!=='monsters')return;const r='resist' in b.dataset,w=r?b.dataset.resist:b.dataset.weak,set=r?resistPick:weakPick;if(!w){weakPick.clear();resistPick.clear()}else if(set.has(w))set.delete(w);else{set.add(w);(r?weakPick:resistPick).delete(w)}q.dispatchEvent(new Event('input'))});
